'use client';

import { Children, type ReactNode, useId, useState } from 'react';

import { cn } from '@/lib/utils';

import styles from './mdx-preview.module.css';

/**
 * Preview / code switcher generated by lib/mdx/remark-mdx-preview.ts from an
 * ```mdx preview fence. Children are `[<MdxPreviewCanvas>, <pre>]`.
 */
export function MdxPreview({ title, children }: { title?: string; children: ReactNode }) {
  const [canvas, code] = Children.toArray(children);
  const [view, setView] = useState<'preview' | 'code'>('preview');
  const id = useId().replace(/:/g, '');

  return (
    <section aria-label={title ? `${title} 示例` : '示例'} className={cn('not-prose', styles.root)}>
      <div className={styles.bar}>
        {title ? <span className={styles.title}>{title}</span> : <span />}
        <div aria-label="示例视图" className={styles.switch} role="tablist">
          {(['preview', 'code'] as const).map((item) => (
            <button
              aria-controls={`${id}-${item}`}
              aria-selected={view === item}
              className={styles.tab}
              id={`${id}-tab-${item}`}
              key={item}
              onClick={() => setView(item)}
              onKeyDown={(event) => {
                if (event.key === 'ArrowRight' || event.key === 'ArrowLeft') {
                  event.preventDefault();
                  const next = item === 'preview' ? 'code' : 'preview';
                  setView(next);
                  document.getElementById(`${id}-tab-${next}`)?.focus();
                }
              }}
              role="tab"
              tabIndex={view === item ? 0 : -1}
              type="button"
            >
              {item === 'preview' ? '预览' : '代码'}
            </button>
          ))}
        </div>
      </div>
      <div aria-labelledby={`${id}-tab-preview`} className={styles.canvas} hidden={view !== 'preview'} id={`${id}-preview`} role="tabpanel">
        {canvas}
      </div>
      <div aria-labelledby={`${id}-tab-code`} className={styles.code} hidden={view !== 'code'} id={`${id}-code`} role="tabpanel">
        {code}
      </div>
    </section>
  );
}

export function MdxPreviewCanvas({ children }: { children: ReactNode }) {
  return <>{children}</>;
}
